<?php
$name = trim((string)($_POST['name'] ?? ''));
$ageInput = (string)($_POST['age'] ?? '');
$valid = $_SERVER['REQUEST_METHOD'] === 'POST' && $name !== '' && filter_var($ageInput, FILTER_VALIDATE_INT) !== false && (int)$ageInput >= 0 && (int)$ageInput <= 130;
function e(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lab 12 — Age Check</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="container"><nav class="page-nav"><a href="index.html">← All labs</a></nav><section class="panel"><p class="eyebrow">LAB 12 · PHP FORM</p><h1>Age Check</h1><form method="post"><div class="form-grid"><label class="field">Name<input name="name" required maxlength="100" value="<?= e($name) ?>"></label><label class="field">Age<input name="age" type="number" min="0" max="130" required value="<?= e($ageInput) ?>"></label></div><button type="submit">Check age</button></form><?php if ($_SERVER['REQUEST_METHOD'] === 'POST'): ?><div class="result <?= $valid && (int)$ageInput < 18 ? 'error' : '' ?>" aria-live="polite"><?php if (!$valid): ?>Please enter a name and a valid age between 0 and 130.<?php elseif ((int)$ageInput < 18): ?>Hello, <?= e($name) ?>, you are not authorized to visit the site.<?php else: ?>Welcome to this site, <?= e($name) ?>.<?php endif; ?></div><?php endif; ?></section></main></body></html>
